exercises.solution:
def total_stock(stock):
    total = 0
    for code in stock:
        total = total + stock[code]
    return total

def articles_disponibles(stock):
    codes = []
    for code in sorted(stock):
        if stock[code] > 0:
            codes.append(code)
    return codes

def articles_en_alerte(stock, seuil):
    codes = []
    for code in sorted(stock):
        if stock[code] < seuil:
            codes.append(code)
    return codes
